'use strict';
window.PrepCheckout=(()=>{
  let status=null,loadedWorkspace=null,loading=false,message='',busy=false,confirmed=null,context=null,observedWorkspace=null,epoch=0,contact={fullName:'',email:''};
  const contextKey=workspace=>'prepspace-interview-return::'+workspace;
  async function api(path,body){const response=await fetch('/api/billing/'+path,{method:body?'POST':'GET',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(state.pilotWorkspaceKey?{'X-PrepSpace-Workspace':state.pilotWorkspaceKey}:{})},...(body?{body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok)throw new Error(value.error||'Billing is unavailable.');return value;}
  function prepare(run){if(run)context={workspace:state.pilotWorkspaceKey,selection:{...run.selection},messages:run.messages.filter(m=>!m.failed).map(m=>({role:m.role,text:m.text,kind:m.kind})),reflection:run.reflection||''};else context={workspace:state.pilotWorkspaceKey,selection:{...(state.studioSetup||{}),minutes:5},messages:[]};}
  function remember(){if(!context)return;sessionStorage.setItem(contextKey(state.pilotWorkspaceKey),JSON.stringify({...context,workspace:state.pilotWorkspaceKey,savedAt:Date.now()}));}
  function restore(){try{const value=JSON.parse(sessionStorage.getItem(contextKey(state.pilotWorkspaceKey))||'null');if(value?.workspace===state.pilotWorkspaceKey&&Date.now()-value.savedAt<3600000&&Array.isArray(value.messages)&&value.messages.reduce((n,m)=>n+(typeof m.text==='string'?m.text.length:100000),0)<=60000)context=value;else sessionStorage.removeItem(contextKey(state.pilotWorkspaceKey));}catch{}}
  function discard(){try{sessionStorage.removeItem(contextKey(state.pilotWorkspaceKey));}catch{}context=null;}
  function page(){const pending=!!route().query.get('session_id')&&!status?.active;return `<div class="checkout-page"><a class="flow-home-link" href="#/">← Back to interview</a><header><span class="studio-eyebrow">KEEP BUILDING YOUR CONFIDENCE</span><h1>${status?.active?'Your subscription is active.':'Keep the conversation going.'}</h1><p>${status?.active?'Continue your interview, or explore the full resource library.':'Your first five AI interview questions are free. Subscribe for unlimited AI mock interview sessions.'}</p></header><div class="checkout-layout"><section class="checkout-plan"><span class="studio-eyebrow">PREPSPACE UNLIMITED</span><div class="checkout-price">£9.99<small> / month</small></div><p class="checkout-renewal">Renews monthly until cancelled. Manage or cancel in Stripe’s billing portal.</p><ul><li>Unlimited AI interview practice</li><li>All roles, domains and supported languages</li><li>Text and push-to-talk voice interviews</li><li>Full learning and coding resources</li></ul><p>One active AI conversation at a time. Internet, microphone permission and service availability apply.</p></section><section class="checkout-details">${status?.active?`<span class="checkout-active">✓ Subscription verified</span><h2>You’re ready to continue.</h2><p>Your access was confirmed by the server, using Stripe’s subscription status.</p><button class="button primary large" data-checkout-resume>${context?.messages?.length?'Resume AI mock interview':'Start AI mock interview'}</button><div class="checkout-resource-links"><a href="/library.html#/learning?language=java">Learning resources ↗</a><a href="/library.html#/lab?round=coding">Coding practice ↗</a></div><button class="button quiet" data-checkout-portal ${busy?'disabled':''}>Manage subscription</button>`:`${pending?'<h2>Verifying your payment</h2><p>Do not pay again while your subscription is being checked. If you completed checkout, use Retry verification below.</p><button class="button" data-checkout-retry>Retry verification</button>':`<h2>Your details</h2><form id="checkout-form"><label>Full name<input name="fullName" autocomplete="name" minlength="2" maxlength="120" required placeholder="Your full name" value="${esc(contact.fullName)}"></label><label>Email address<input type="email" name="email" autocomplete="email" maxlength="254" required placeholder="you@example.com" value="${esc(contact.email)}"></label><label class="checkout-consent"><input type="checkbox" name="consent" required><span>I agree to a recurring £9.99 GBP monthly subscription, renewing until I cancel.</span></label><p class="checkout-privacy">Your name and email are sent to Stripe to set up your subscription. Card details are entered only on Stripe’s secure checkout. Interview context is kept temporarily in this tab for up to one hour so you can resume after payment; it is cleared when resumed or discarded. <a href="/privacy.html" target="_blank" rel="noopener noreferrer">Privacy page</a>.</p><button class="button primary large" ${!status?.enabled||status?.signedIn===false||busy?'disabled':''}>${busy?'Opening secure checkout…':'Subscribe with Stripe →'}</button></form>${status?.signedIn===false?'<p class="checkout-notice">Sign in to your account before starting checkout.</p>':''}${status&&!status.enabled?'<p class="checkout-notice">Checkout is being configured. No payment details can be submitted yet.</p>':''}<small class="checkout-secure">Secure checkout provided by Stripe</small>`}`}<p class="checkout-message" role="status">${esc(message||(!status?'Checking subscription options…':''))}</p>${context?'<button class="button quiet small" data-checkout-discard>Discard saved interview context</button>':''}${status?.testMode?'<span class="checkout-test-mode">Stripe test mode · No live payment</span>':''}</section></div></div>`;}
  async function mount(){
    if(route().path!=='checkout')return;await window.PrepPilotUI.ensureWorkspace();const workspace=state.pilotWorkspaceKey;
    if(observedWorkspace!==workspace){epoch++;observedWorkspace=workspace;status=null;loadedWorkspace=null;loading=false;message='';confirmed=null;if(context?.workspace!==workspace)context=null;contact={fullName:'',email:''};}
    if(loading||loadedWorkspace===workspace)return;const token=++epoch;loading=true;loadedWorkspace=workspace;restore();
    try{const id=route().query.get('session_id');if(id&&confirmed!==id){const verified=await api('confirm',{checkoutId:id});if(token!==epoch||workspace!==state.pilotWorkspaceKey)return;message=verified.active?'Payment verified. You can continue your interview.':'Payment is still pending. Access unlocks only after Stripe confirms it.';if(verified.active){confirmed=id;history.replaceState(null,'','#/checkout');}}
      const next=await api('status');if(token!==epoch||workspace!==state.pilotWorkspaceKey)return;status=next;if(!status.active&&route().query.get('cancelled')==='1')message='Checkout was cancelled. You can return to your interview or subscribe later.';
    }catch(error){if(token===epoch&&workspace===state.pilotWorkspaceKey)message=error.message;}
    finally{if(token===epoch){loading=false;if(route().path==='checkout')render();}}
  }
  document.addEventListener('input',event=>{if(event.target.closest?.('#checkout-form')&&['fullName','email'].includes(event.target.name))contact[event.target.name]=event.target.value;});
  document.addEventListener('submit',async event=>{if(event.target.id!=='checkout-form')return;event.preventDefault();if(busy||!status?.enabled)return;const workspace=state.pilotWorkspaceKey,form=Object.fromEntries(new FormData(event.target));contact={fullName:form.fullName,email:form.email};busy=true;message='';const button=event.target.querySelector('button');button.disabled=true;button.textContent='Opening secure checkout…';try{remember();const result=await api('checkout',{fullName:form.fullName,email:form.email,consent:form.consent==='on',requestId:crypto.randomUUID()});if(workspace!==state.pilotWorkspaceKey)throw new Error('Your account changed. Reload before continuing.');const url=new URL(result.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw new Error('The checkout destination could not be verified.');location.assign(result.url);}catch(error){message=error.message;busy=false;render();}});
  document.addEventListener('click',async event=>{if(event.target.closest('[data-checkout-retry]')){loadedWorkspace=null;confirmed=null;render();}if(event.target.closest('[data-checkout-discard]')){discard();message='Saved interview context has been discarded.';render();}if(event.target.closest('[data-checkout-portal]')){const workspace=state.pilotWorkspaceKey;busy=true;try{const result=await api('portal',{});if(workspace!==state.pilotWorkspaceKey)throw new Error('Your account changed. Reload before continuing.');const url=new URL(result.url);if(url.protocol!=='https:'||url.hostname!=='billing.stripe.com')throw new Error('Invalid billing destination.');location.assign(url.href);}catch(error){message=error.message;busy=false;render();}}if(event.target.closest('[data-checkout-resume]')&&status?.active){const saved=context;discard();window.InterviewStudio.resume(saved);go('');}});
  return {page,mount,prepare,discard};
})();
